package com.MITProjectService.bot.dao.jpaRepos;import com.MITProjectService.bot.domain.Bookings;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.JpaSpecificationExecutor;import org.springframework.data.jpa.repository.Query;import org.springframework.stereotype.Repository;import java.util.List;@Repositorypublic interface BookingServiceRepository extends JpaRepository<Bookings,Long > , JpaSpecificationExecutor<Bookings> {    @Query("select b from Bookings b where b.user.id = :userId")    List<Bookings> getBookingsByUserId(Long userId);    @Query("select b from Bookings b where b.services.serviceProvider.id = :userId")    List<Bookings> getBookingsByServiceProviderId(Long userId);}